// TH15 st03 MainSub04:1576-1616, source local frame 0 after opening buffer.
const TIME_LIMIT: int = 2024;
const OPENING_BUFFER: int = 120;
const TH15_RING_BALL2: int = 464; // source type 7
const TH15_STAR_R: int = 608; // source type 16

// ECir02DeadAttackEt1: ANIM omitted except its -4*velocity birth displacement.
// Independent WAIT retained; VELTIME has keep-angle sentinel, so scalar ramp is collinear.
xformdef DEAD_RAMP(delay: int, target: fx) {
    wait(delay);
    @60 set_accel((target-1.2fx)/60);
    set_accel(0fx);
    set_speed(target);
}

async sub dead_emitter() {
    // Source flagSet(288): noninteractive helper, static at parent's death position.
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    var rank: int = global(GVAR_RANK);
    var n: int = 1;
    if rank == 1 { n = 3; }
    if rank >= 2 { n = 5; }
    var delay: int = 90;
    var target: fx = 4fx;
    var bursts: int = 4;
    if rank == 3 { delay = 40; target = 5fx; bursts = 8; }
    // Source 239-274: fixed fan; 1 layer uses speed 1.2, not the unused endpoint 0.2.
    sh_reset(0);
    sh_sprite(0, TH15_STAR_R, 6);
    sh_count(0, n, 1);
    sh_speed(0, 1.2fx, 0fx);
    sh_dist(0, -4.8fx);
    sh_xform(0, DEAD_RAMP(delay, target));
    // 279-284: refresh ANGLE_PLAYER at each of 4/8 shots, spaced 7 frames.
    for b in 0..bursts {
        sh_angle(0, aim_player(), 45deg);
        sh_fire(0);
        wait(7);
    }
}

async sub circle_enemy(a: angle) {
    // Source ECir02:202-223; F0 inherited as a birth snapshot.
    set_invuln(65535);
    set_hitbox(8fx);
    set_hurtbox(12fx);
    move_vel(0, a, 2fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    // Approved synthesis: invoke death attack ONCE at age120, then remove parent.
    // DeadAttack1's F0/I0/I1 assignments are unused by its child; do not invent shots.
    wait(120);
    _ = spawn_enemy($self_x, $self_y, 10, 0, 0, 0, dead_emitter);
}

sub girl_ring(n: int, top_speed: fx) {
    // GirlD01_at:871-899, mode9 N x17 alternating-layer rings.
    // Cache A once per entire etOn, then visit layers q in original order.
    var aim: angle = aim_player();
    sh_reset(0);
    sh_sprite(0, TH15_RING_BALL2, 2);
    sh_ring(0, 1);
    sh_count(0, n, 1);
    for q in 0..17 {
        var k: int = ((q+1)/2)*2;
        var speed: fx = top_speed+(1.8fx-top_speed)*k/16;
        var h: int = ((q+1)/2)*273; // 0.02617994rad, nearest BAM = 1.5deg
        if q%2 != 0 { h = -h; }
        // Odd layers reverse native ring creation order. The same angular point set
        // is emitted here; there is no random/EX/order-dependent consumer on these bullets.
        sh_angle(0, aim+(h as angle), 0deg);
        sh_speed(0, speed, 0fx);
        sh_dist(0, -4fx*speed); // retained ANIM retreat per bullet
        sh_fire(0);
    }
}
async sub girl_attack() {
    // Spawn task starts next tick: wait59 preserves the source's age60 first shot.
    wait(59);
    var rank: int = global(GVAR_RANK);
    var n: int = 10;
    var top_speed: fx = 2.6fx;
    var bursts: int = 4;
    var gap: int = 125;
    if rank == 0 { n = 5; bursts = 2; }
    if rank == 2 { top_speed = 3.2fx; bursts = 6; gap = 90; }
    if rank == 3 { top_speed = 3.5fx; bursts = 6; gap = 90; }
    for b in 0..bursts {
        girl_ring(n, top_speed);
        wait(gap);
    }
}
async sub girl_enemy() {
    // GirlD01:841-865. Cosmetic unknown569/ANM/drops omitted by shared policy.
    set_invuln(65535);
    set_hitbox(12fx);
    set_hurtbox(16fx);
    move_vel(0, 90deg, 2.5fx, EASE_LINEAR);
    move_vel(70, 90deg, 0fx, EASE_QUAD_IN);
    spawn girl_attack();
    wait(80);
    move_speed(120, 0.2fx, EASE_QUAD_IN);
    wait(400);
    move_speed(120, 3fx, EASE_QUAD_IN);
    // Source waits forever; engine's normal offscreen retirement ends this enemy.
    loop { wait(1000); }
}
async sub pattern() {
    wait(OPENING_BUFFER);
    // Source MainSub04:1576. No upstream waves or chapter/boss gates.
    wait(130);
    _ = spawn_enemy(32fx, -24fx, 1200, 0, 0, 0, girl_enemy);
    _ = spawn_enemy(-32fx, -24fx, 1200, 0, 0, 0, girl_enemy);
    wait(260);
    // 1580/1592/1604 reset x=192 and F0=pi/2 independently on each row.
    for row in 0..3 {
        var x: fx = 192fx;
        var a: int = 16384;
        for i in 0..20 {
            a = a+182; // 0.017453rad before each creation
            _ = spawn_enemy(x, -32fx, 100, 0, 0, 0, circle_enemy(a as angle));
            x = x-17fx;
            wait(10);
        }
        if row < 2 { wait(60); }
    }
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
